def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    explored_content = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zip_ref:
            for file_info in zip_ref.infolist():
                if file_info.filename.endswith('/'):  # directory
                    if file_info.filename in explored_content:
                        explored_content[file_info.filename].append(None)
                    else:
                        explored_content[file_info.filename] = [None] * 1024  # initial data

                else:  # file
                    file_name = file_info.filename
                    file_data = zip_ref.read(file_name)
                    if file_name in explored_content:
                        if file_info.filename not in explored_content[file_name]:
                            explored_content[file_name].append(file_data)
                    else:
                        explored_content[file_name] = [file_data]

    except Exception as e:
        # Handle any exceptions, e.g., invalid file path, zip file error, etc.
        print(f"An error occurred: {e}")
