def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    class PrettyPrinter:
        def __init__(self, indent):
            self.indent = indent

        def _format(self, node):
            if isinstance(node, list):
                return '\n'.join(self._format(item) for item in node)
            elif isinstance(node, dict):
                return '\n'.join('{}{}: {}'.format(
                    self.indent, key, self._format(value))
                    for key, value in node.items())
            elif isinstance(node, str):
                return self.keyval(node, indent)
            else:
                return str(node)

        def keyval(self, node, indent):
            if debug:
                return 'keyval debug({}, {})'.format(node, indent)
            return '{}\'{}\''.format(self.indent, node)

    return PrettyPrinter(indent)(self).__format__()
