def addignored(ignored):
    """ Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma."""

    def git(*args, error_message=None, cwd=None, **kwargs):
        output, status = subprocess.check_output(["git"] + list(args), cwd=cwd)
        if status != 0:
            if error_message:
                kwargs['output'] = output
                kwargs['directory'] = cwd
                raise subprocess.CalledProcessError(error_message, **kwargs)
            else:
                raise subprocess.CalledProcessError(str(output), cwd=cwd)

    ignored_files = git("ls-files --pattern='{0}'".format(ignored))
    ignored_files = [line.strip() for line in ignored_files.decode().split('\n') if line.strip()]
    ignored_files.sort()

    return ",".join(ignored_files)
